head.script:
// 화면 리사이징

scwin.gIsurCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
        scwin.init();
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF33050.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    // 한달전 날짜
    rdo_MKT_ID.setValue(js_market);
    if (js_market !== "9") {
        panel_mkt.hide();
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF33050.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF33050.xml", SCREN_PROCS_TP_CD_07, '');
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "지주회사및자회사목록", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF33050.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF33050.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF33050.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_ISUR_CD_onclick
 * @description btn_ISUR_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ISUR_CD_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF33050.btn_ISUR_CD_onclick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF33050.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF33050.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF33050.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF33050.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF33050.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF33050.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF33050.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onfocus
 * @description txb_ISUR_CD 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onfocus = function() {
    try {
        if (rdo_PARNTCOM_KIND_TP_CD.getValue() === '1') {
            Grd_com_isur.style.display = "";
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF33050.txb_ISUR_CD_onfocus" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onkeyup
 * @description txb_ISUR_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onkeyup = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF33050.txb_ISUR_CD_onkeyup" });
    }
};

/**
 * @method
 * @name rdo_PARNTCOM_KIND_TP_CD_onselchange
 * @description rdo_PARNTCOM_KIND_TP_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_PARNTCOM_KIND_TP_CD_onselchange = function() {
    try {
        txb_ISUR_CD.setValue('');
        txb_COM_NM.setValue('');
        if (rdo_PARNTCOM_KIND_TP_CD.getValue() === '1') {
            txb_ISUR_CD.setReadOnly(false);
            txb_ISUR_CD.style.backgroundColor = '#ffffff';
            txb_COM_NM.setReadOnly(true);
            txb_COM_NM.style.backgroundColor = '#b9d4f7';
            btn_ISUR_CD.setDisabled(false);
        } else if (rdo_PARNTCOM_KIND_TP_CD.getValue() === '2') {
            txb_ISUR_CD.setReadOnly(true);
            txb_ISUR_CD.style.backgroundColor = '#b9d4f7';
            txb_COM_NM.setReadOnly(false);
            txb_COM_NM.style.backgroundColor = '#ffffff';
            btn_ISUR_CD.setDisabled(true);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF33050.rdo_PARNTCOM_KIND_TP_CD_onselchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/LnkDisclsApplCorp.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};
